form .add-row-btn, 
form .remove-row-btn {
    height: 24px;
    padding: 0;
    border: 2px solid var(--border-color);
    border-radius: 10px;
    box-sizing: border-box;
    cursor: pointer;
    align-self: end;
}

form .add-row-btn {
    margin: 0 10px;
    background-color: transparent;
}

form .remove-row-btn {
    background-color: var(--dark-button-color);
}

form .step-wrapper {
    display: flex;
    justify-content: start;
}

form .step-wrapper textarea {
    width: 100%;
    height: 3rem;
    margin: 0 10px 5px 0;
    padding: 2px 4px;
    border-radius: 5px;
    background-color: var(--light-bg-color);
    border-width: 1px 1px 2px 1px;
    border-style: solid;
    border-color: var(--border-color);
    resize: none;
}

form .selector__wrapper {
    width: 100px;
}

form .plus-icon, 
form .x-icon {
    height: 16px;
    padding: 2px 8px;
}

.ingredient .labeled-input {
    display: flex;
    flex-direction: column;
}

.ingredient .labeled-input span {
    color: var(--dark-text-color)
}

.ingredient .labeled-input + .labeled-input {
    margin-left: 10px;
