___CSS_LOADER_EXPORT___.push([module.id, `form input:not([type="file"])  {
    height: 24px;
    padding: 2px 4px;
    border-radius: 5px;
    background-color: var(--light-bg-color);
    border-width: 1px 1px 2px 1px;
    border-style: solid;
    border-color: var(--border-color);
}

form input + input {
    margin-left: 10px;
}

.form-container {
    display: flex;
    flex-direction: column;
    align-items: center;

    height: calc(75% - 50px);
    padding: 40px;
    
    background-color: var(--light-bg-color);
    border: 4px solid var(--border-color);
    border-radius: 10px;
    color: var(--dark-text-color);
}

.form-container form {
    width: 100%;
}

.form-container h1 {
    margin: 0 0 40px 0;
}

.form-container h2 {
    margin: 20px 0 10px 0;
}

.form-container label {
    display: flex;
    flex-direction: column;
}

.form-container p {
    margin: 0;
}

.form-container .centered-form {
    display: flex;
    flex-direction: column;
    align-items: center;
}

.form-container .text-link {
    text-decoration: underline;
    cursor: pointer;
}

.form-container .text-link__container {
    margin: 10px 0 0;
}

.form-container .button {
    margin-top: 20px;
}

.input-control {
    position: relative;
}

.input-control + .input-control {
    margin-top: 20px;
}

.input-error {
    position: absolute;
    bottom: calc(-1em - 2px);
    left: 0;
    font-size: 14px;
    color: var(--error-color);
}

.form-buttons-container {
    display: flex;
    align-items: center;
    justify-content: center;
}

input::file-selector-button {
    padding: 5px 10px;
    color: var(--dark-text-color);
    border: 2px solid var(--border-color);
    background-color: var(--light-bg-color);
    border-radius: 6px;
    cursor: pointer;
}

@media (max-width: 540px) {
    .form-container {
        height: calc(100% - 40px);
        width: calc(100% - 40px);
        padding: 20px;
    }
}
