#header {
    position: fixed;
    top: 0;
    left: 0;
    
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 50px;
    width: 100%;

    background-color: var(--main-header-color);
    z-index: 1000000;
}

#header__logo {
    margin-left: 20px;
    height: 36px;
}

#menu {
    position: absolute;    
    top: 7px;
    right: 0;
    width: 36px;
    height: 36px;
    margin-right: 20px;
    padding: 10px;

    display: flex;
    flex-direction: column;

    background-color: var(--light-bg-color);
    border: 2px solid var(--border-color);
    border-radius: 50%;

    overflow: hidden;
    transition: width 400ms ease-in-out, height 400ms ease-in-out, border-radius 100ms ease 350ms;
}

#menu.expanded {
    width: 250px;
    height: 200px;
    border-radius: 10px;
    transition: width 400ms ease-in-out 100ms, height 400ms ease-in-out 100ms, border-radius 200ms ease-out;
}

#menu__icon-container {
    position: absolute;
    right: 0;
    top: 0;
    width: 32px;
    height: 32px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 50%;
    background-color: var(--light-bg-color);
    cursor: pointer;
}

#menu__container {
    width: 100%;
    height: 100%;
    color: var(--dark-text-color);
    background-color: var(--light-bg-color);
}

#menu__container ul {
    margin: 20px 0 0;
    padding: 10px;
    list-style: none;
    padding-inline-start: 0;
}

#menu__container h2 {
    margin: 0;
}

#menu .menu-icon {
    width: 18px;
    height: 18px;
}

#menu__container ul li + li {
    margin-top: 10px;
}

#menu a {
    display: flex;
    align-items: center;
    padding: 4px;
    text-decoration: none;
    color: var(--dark-text-color);
    border-width: 1px;
    border-style: solid;
    border-radius: 10px;
    border-color: var(--border-color);
    cursor: pointer;
}

#menu nav a.active {
    background-color: var(--contrast-button-color);
}

#menu a svg {
    height: 18px;
    margin-right: 4px;
}

#menu a span {
    font-size: 18px;
}

#menu a:visited {
    color: var(--dark-text-color);
}

@media (max-width: 480px) {
    #header__logo {
        margin-left: 5px;
    }
