#profile-form {
    width: 400px;
    height: 100%;
    display: flex;
    flex-direction: column;
}

#profile-form__data-container {
    display: flex;
    height: 100%;
}

#profile-form__image-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin-right: 20px;
}

#profile-form__input-container {
    width: 100%;
}

#profile-form #profile-img {
    height: 128px;
    width: 128px;
    object-fit: cover;
    border-radius: 50%;
    background-color: var(--main-bg-color);
    border: 5px solid var(--border-color);
}

#profile-form #avatar-btn {
    width: 120px;
    margin-top: 10px;
}

#profile-form h1 {
    text-align: center;
    margin-bottom: 40px;
}

#profile-form #logout-btn {
    margin-left: 20px;
    background-color: var(--dark-button-color);
}

@media (max-width: 480px) {
    #profile-form {
        width: 100%;
        height: 100%;
    }

    #profile-form__data-container {
        flex-direction: column;
        width: 100%;
    }

    #profile-form__image-container {
        margin-right: 0;
        margin-bottom: 20px;
    }
